// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.agent.automationimport android.graphics.Bitmap/** * NOUS — Automation Operations (Module 9 v1 — Step 9.2). * * Sealed class hierarchy representing all automation operations that * [AutomationProvider] implementations can execute. * * Each operation maps to a real Android action: *  - [Tap] → AccessibilityService.dispatchGesture() or LADB "input tap" *  - [Swipe] → AccessibilityService.dispatchGesture() or LADB "input swipe" *  - [LongPress] → AccessibilityService.dispatchGesture() or LADB "input swipe" (long duration) *  - [TypeText] → AccessibilityNodeInfo.ACTION_SET_TEXT or LADB "input text" *  - [ClickButtonByText] → findAccessibilityNodeInfosByText + ACTION_CLICK *  - [PressKey] → performGlobalAction or LADB "input keyevent" *  - [TakeScreenshot] → AccessibilityService.takeScreenshot() or LADB "screencap" *  - [GetUiTree] → rootInActiveWindow traversal * * @see <a href="docs/strategy/module-9-agent-strategy-v1.md">§Step 9.2</a> */sealed interface AutomationOperation {    /** Tap at a screen coordinate. */    data class Tap(        val x: Float,        val y: Float,    ) : AutomationOperation    /** Swipe from one point to another. */    data class Swipe(        val startX: Float,        val startY: Float,        val endX: Float,        val endY: Float,        val durationMs: Long = 300,    ) : AutomationOperation    /** Long-press at a screen coordinate. */    data class LongPress(        val x: Float,        val y: Float,        val durationMs: Long = 1000,    ) : AutomationOperation    /** Type text into the focused input field. */    data class TypeText(        val text: String,    ) : AutomationOperation    /** Click a button by its visible text (e.g., "Send", "Reply"). */    data class ClickButtonByText(        val buttonText: String,    ) : AutomationOperation    /** Click a button by its view ID (e.g., "com.whatsapp:id/send"). */    data class ClickButtonByViewId(        val viewId: String,    ) : AutomationOperation    /** Press a hardware/system key (back, home, recents, etc.). */    data class PressKey(        val keyCode: Int,    ) : AutomationOperation    /** Take a screenshot of the current screen. */    data object TakeScreenshot : AutomationOperation    /** Get the current UI tree (for screen reading). */    data object GetUiTree : AutomationOperation    /** Open an app by package name. */    data class OpenApp(        val packageName: String,    ) : AutomationOperation    /** Scroll in a direction. */    data class Scroll(        val direction: ScrollDirection,    ) : AutomationOperation}/** Scroll directions. */enum class ScrollDirection(val displayName: String) {    UP("Up"),    DOWN("Down"),    LEFT("Left"),    RIGHT("Right"),}// ──────────────────────────────────────────────────────────────────────────/** * Result of an automation operation. */sealed interface AutomationResult {    /** Operation succeeded. */    data class Success(        val operation: AutomationOperation,        val durationMs: Long,        val data: AutomationResultData? = null,    ) : AutomationResult    /** Operation failed. */    data class Failure(        val operation: AutomationOperation,        val reason: String,        val durationMs: Long,    ) : AutomationResult    /** Operation not supported by this provider. */    data class NotSupported(        val operation: AutomationOperation,        val providerName: String,    ) : AutomationResult    /** True if this is a [Success]. */    val isSuccess: Boolean get() = this is Success    /** True if this is a [Failure]. */    val isFailure: Boolean get() = this is Failure}/** Extra data returned with a [AutomationResult.Success]. */sealed interface AutomationResultData {    /** Screenshot bitmap (from TakeScreenshot). */    data class Screenshot(val bitmap: Bitmap) : AutomationResultData    /** UI tree snapshot (from GetUiTree). */    data class UiTree(val snapshot: UiTreeSnapshot) : AutomationResultData    /** Simple boolean result (from tap/swipe/click). */    data class BooleanResult(val value: Boolean) : AutomationResultData}